<script>
'use strict';
/* ============================================================
 * CHIP-8 Emulator — single-file, no dependencies
 * ============================================================ */

const FONT_START = 0x050;
const PROG_START = 0x200;
const W = 64, H = 32;

const FONT = [
  0xF0,0x90,0x90,0x90,0xF0, // 0
  0x20,0x60,0x20,0x20,0x70, // 1
  0xF0,0x10,0xF0,0x80,0xF0, // 2
  0xF0,0x10,0xF0,0x10,0xF0, // 3
  0x90,0x90,0xF0,0x10,0x10, // 4
  0xF0,0x80,0xF0,0x10,0xF0, // 5
  0xF0,0x80,0xF0,0x90,0xF0, // 6
  0xF0,0x10,0x20,0x40,0x40, // 7
  0xF0,0x90,0xF0,0x90,0xF0, // 8
  0xF0,0x90,0xF0,0x10,0xF0, // 9
  0xF0,0x90,0xF0,0x90,0x90, // A
  0xE0,0x90,0xE0,0x90,0xE0, // B
  0xF0,0x80,0x80,0x80,0xF0, // C
  0xE0,0x90,0x90,0x90,0xE0, // D
  0xF0,0x80,0xF0,0x80,0xF0, // E
  0xF0,0x80,0xF0,0x80,0x80  // F
];

/* ---- Core state ---- */
const memory = new Uint8Array(4096);
const V = new Uint8Array(16);        // V0..VF
let I = 0;                          // index register
let PC = PROG_START;
const stack = [];
let DT = 0, ST = 0;                 // delay / sound timers
const keys = new Uint8Array(16);    // 0..0xF
const gpx = new Uint8Array(W);      // sprite x-height
const gpy = new Uint8Array(H);      // sprite y-height
let gpxc = false, gpyc = false;

const canvas = document.getElementById('screen');
const ctx = canvas.getContext('2d');
const img = ctx.createImageData(W, H);

/* ---- Sound (WebAudio beep, best-effort) ---- */
let audioCtx = null, osc = null, gainNode = null;
function audioInit() {
  if (audioCtx) return;
  try {
    audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    osc = audioCtx.createOscillator();
    gainNode = audioCtx.createGain();
    osc.type = 'square';
    osc.frequency.value = 440;
    gainNode.gain.value = 0;
    osc.connect(gainNode);
    gainNode.connect(audioCtx.destination);
    osc.start();
  } catch (e) { audioCtx = null; }
}
function audioTick() {
  if (!audioCtx || !gainNode) return;
  const v = ST > 0 ? 0.06 : 0;
  try { gainNode.gain.setTargetAtTime(v, audioCtx.currentTime, 0.01); } catch (e) {}
