/* ---- Display ---- */
function render() {
  const d = img.data;
  for (let i = 0; i < W * H; i++) {
    d[i*4]   = 233; // R
    d[i*4+1] =  69; // G
    d[i*4+2] =  96; // B
    d[i*4+3] = 255;
  }
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      if (gpx[x] > y) {
        const i = (y * W + x) * 4;
        d[i] = 0; d[i+1] = 0; d[i+2] = 0;
      }
    }
  }
  ctx.putImageData(img, 0, 0);
}

function clearDisplay() {
  gpx.fill(0); gpy.fill(0);
  gpxc = false; gpyc = false;
}

function drawSprite(x, y, n) {
  x &= 0x3F;
  let collision = false;
  for (let s = 0; s < n; s++) {
    const row = memory[I + s];
    const rowY = (y + s) & 0x1F;
    if (gpxc && gpyc) break;
    for (let b = 0; b < 8; b++) {
      if (row & (0x80 >> b)) {
        const px = (x + b) & 0x3F;
        const was = gpx[px] > rowY;
        gpx[px] = was ? 0 : rowY + 1;
        if (!was) gpy[px] = rowY + 1;
        if (was) collision = true;
      }
    }
  }
  V[0xF] = collision ? 1 : 0;
  render();
