/* ---- Instruction decoding helpers ---- */
function hex2(n, w) { return '0x' + n.toString(16).toUpperCase().padStart(w, '0'); }

function decode(op) {
  const kk = (op & 0xF00) === 0x000;
  const nn = (op & 0x0F0) >>> 4;
  switch (op & 0xF000) {
    case 0x0000:
      if (op === 0x00E0) return { text: 'CLRE0', desc: 'Clear display' };
      if (op === 0x00EE) return { text: 'RET',   desc: 'Return from subroutine' };
      if (kk) return { text: 'SYS nn', desc: 'System call (ignored)' };
      return { text: '0nnn', desc: 'Unknown' };
    case 0x1000: return { text: 'JP ' + hex2(op & 0x0FFF, 4), desc: 'Jump to address' };
    case 0x2000: return { text: 'CALL ' + hex2(op & 0x0FFF, 4), desc: 'Call subroutine' };
    case 0x3000: return { text: 'SE V' + nn + ' ' + hex2(op & 0xFF, 2), desc: 'If V' + nn + ' == nn' };
    case 0x4000: return { text: 'SNE V' + nn + ' ' + hex2(op & 0xFF, 2), desc: 'If V' + nn + ' != nn' };
    case 0x5000: return { text: 'SE V' + nn + ' V' + (op & 0xF), desc: 'If V' + nn + ' == V' + (op & 0xF) };
    case 0x6000: return { text: 'LD V' + nn + ' ' + hex2(op & 0xFF, 2), desc: 'V' + nn + ' = nn' };
    case 0x7000: return { text: 'ADD V' + nn + ' ' + hex2(op & 0xFF, 2), desc: 'V' + nn + ' += nn (no VF)' };
