        case 0x2: return { text: 'AND V' + nn + ' V' + x, desc: 'V' + nn + ' &= V' + x };
        case 0x3: return { text: 'XOR V' + nn + ' V' + x, desc: 'V' + nn + ' ^= V' + x };
        case 0x4: return { text: 'ADD V' + nn + ' V' + x, desc: 'V' + nn + ' += V' + x, VF=carry' };
        case 0x5: return { text: 'SUB V' + nn + ' V' + x, desc: 'V' + nn + ' -= V' + x, VF=not borrow' };
        case 0x6: return { text: 'SHR V' + nn, desc: 'V' + nn + ' >>= 1, VF=LSB' };
        case 0x7: return { text: 'SUBN V' + nn + ' V' + x, desc: 'V' + nn + ' = V' + x + ' - V' + nn + ', VF=not borrow' };
