      }
      return { text: '8nn? ', desc: 'Unknown' };
    }
    case 0x9000: return { text: 'SNE V' + nn + ' V' + (op & 0xF), desc: 'If V' + nn + ' != V' + (op & 0xF) };
    case 0xA000: return { text: 'LD I ' + hex2(op & 0x0FFF, 4), desc: 'I = address' };
    case 0xB000: return { text: 'JP V0 ' + hex2(op & 0x0FFF, 4), desc: 'Jump to address + V0' };
    case 0xC000: return { text: 'RND V' + nn + ' ' + hex2(op & 0xFF, 2), desc: 'V' + nn + ' = random & nn' };
    case 0xD000: return { text: 'DRW V' + nn + ' V' + (op & 0xF) + ' ' + hex2(op & 0xF, 1), desc: 'Draw sprite' };
    case 0xE000:
      if ((op & 0xFF) === 0x9E) return { text: 'SKP V' + nn, desc: 'If key V' + nn + ' pressed' };
      if ((op & 0xFF) === 0xA1) return { text: 'SKNP V' + nn, desc: 'If key V' + nn + ' not pressed' };
      return { text: 'Ennn', desc: 'Unknown' };
    case 0xF000:
      switch (op & 0xFF) {
        case 0x01: return { text: 'LDR V' + nn + ' DT', desc: 'V' + nn + ' = delay timer' };
        case 0x0A: return { text: 'LD DT V' + nn, desc: 'delay timer = V' + nn };
        case 0x15: return { text: 'LD ST V' + nn, desc: 'sound timer = V' + nn };
        case 0x18: return { text: 'LD V' + nn + ' RT', desc: 'V' + nn + ' = random timer' };
        case 0x1E: return { text: 'ADD I V' + nn, desc: 'I += V' + nn + ' (no VF)' };
        case 0x29: return { text: 'LD F V' + nn, desc: 'I = font sprite of V' + nn };
        case 0x33: return { text: 'BCD V' + nn, desc: 'Store BCD of V' + nn + ' at I' };
        case 0x55: return { text: 'LD [I] V0..' + nn, desc: 'memory[I..] = V0..V' + nn };
        case 0x65: return { text: 'LD V0..' + nn + ' [I]', desc: 'V0..V' + nn + ' = memory[I..]' };
      }
      return { text: 'Fnn?', desc: 'Unknown' };
  }
  return { text: '????', desc: 'Unknown' };
}

/* ---- Instruction execution ---- */
function step() {
  const op = (memory[PC] << 8) | memory[PC + 1];
  const nn = (op & 0x0F0) >>> 4;
  const x = op & 0xF;
  const dec = decode(op);
  showInstr(dec);

  switch (op & 0xF000) {
    case 0x0000:
      if (op === 0x00E0) clearDisplay();
      else if (op === 0x00EE) { PC = stack.pop(); if (PC === undefined) PC = PROG_START; }
      break; // SYS: ignored
    case 0x1000: PC = (op & 0x0FFF); break;
    case 0x2000:
      stack.push(PC + 2);
      PC = (op & 0x0FFF);
      break;
    case 0x3000: if (V[nn] === (op & 0xFF)) PC += 4; break;
    case 0x4000: if (V[nn] !== (op & 0xFF)) PC += 4; break;
    case 0x5000: if (V[nn] === V[x]) PC += 4; break;
    case 0x6000: V[nn] = op & 0xFF; break;
    case 0x7000: V[nn] = (V[nn] + (op & 0xFF)) & 0xFF; break;
    case 0x8000:
      switch (op & 0x000F) {
        case 0x0: V[nn] = V[x]; break;
        case 0x1: V[nn] = (V[nn] | V[x]) & 0xFF; break;
        case 0x2: V[nn] = (V[nn] & V[x]) & 0xFF; break;
        case 0x3: V[nn] = (V[nn] ^ V[x]) & 0xFF; break;
        case 0x4: {
          const sum = V[nn] + V[x];
          V[nn] = sum & 0xFF;
          V[0xF] = sum > 0xFF ? 1 : 0;
        } break;
        case 0x5: {
          const noBorrow = (V[nn] >= V[x]) ? 1 : 0;
          V[nn] = (V[nn] - V[x]) & 0xFF;
          V[0xF] = noBorrow;
        } break;
        case 0x6:
          V[0xF] = V[nn] & 1;
          V[nn] = V[nn] >>> 1;
          break;
        case 0x7: {
          const noBorrow = (V[x] >= V[nn]) ? 1 : 0;
          V[nn] = (V[x] - V[nn]) & 0xFF;
          V[0xF] = noBorrow;
        } break;
        case 0xE:
          V[0xF] = (V[nn] & 0x80) ? 1 : 0;
          V[nn] = (V[nn] << 1) & 0xFF;
          break;
      }
      break;
    case 0x9000: if (V[nn] !== V[x]) PC += 4; break;
    case 0xA000: I = op & 0x0FFF; break;
    case 0xB000: PC = (op & 0x0FFF); break;
    case 0xC000: V[nn] = (Math.floor(Math.random() * 256)) & (op & 0xFF); break;
    case 0xD000: drawSprite(V[nn], V[x], op & 0xF); break;
    case 0xE000:
      if ((op & 0xFF) === 0x9E) { if (keys[V[nn] & 0xF]) PC += 4; }
      else if ((op & 0xFF) === 0xA1) { if (!keys[V[nn] & 0xF]) PC += 4; }
      break;
    case 0xF000:
      switch (op & 0xFF) {
        case 0x01: V[nn] = DT; break;
        case 0x0A: DT = V[nn]; break;
        case 0x15: ST = V[nn]; break;
        case 0x18: V[nn] = (Math.floor(Math.random() * 256)); break;
        case 0x1E: I = (I + V[nn]) & 0xFFFF; break;
        case 0x29: I = FONT_START + (V[nn] & 0xF) * 5; break;
        case 0x33: {
          const v = V[nn];
          memory[I]     = Math.floor(v / 100) & 0xFF;
          memory[I + 1] = Math.floor(v / 10) % 10;
          memory[I + 2] = v % 10;
        } break;
        case 0x55: for (let k = 0; k <= nn; k++) memory[I + k] = V[k]; break;
        case 0x65: for (let k = 0; k <= nn; k++) V[k] = memory[I + k]; break;
      }
      break;
  }
  PC = (PC + 2) & 0xFFFF;
  audioTick();
}

/* ---- Timers (60 Hz) ---- */
function tickTimers() {
  if (DT > 0) DT--;
  if (ST > 0) ST--;
  audioTick();
}

/* ---- ROM loading ---- */
function loadROM(bytes, name) {
  // normalize: if first two bytes are a plausible program counter, strip
  let src = bytes;
  if (bytes.length > 2) {
    const first = (bytes[0] << 8) | bytes[1];
    if (first >= 0x0200 && first < 0xFFFF) src = bytes.slice(2);
  }
  memory.fill(0);
  V.fill(0);
  for (let i = 0; i < FONT.length; i++) memory[FONT_START + i] = FONT[i];
  for (let i = 0; i < src.length; i++) memory[PROG_START + i] = src[i];
  I = 0; PC = PROG_START;
  stack.length = 0;
  DT = 0; ST = 0;
  keys.fill(0);
  clearDisplay();
  render();
  setStatus(name + ' loaded (' + src.length + ' bytes)', true);
  updateUI();
}

function setStatus(msg, ok) {
  const el = document.getElementById('status');
  el.textContent = msg;
  el.className = 'status' + (ok === true ? ' ok' : ok === false ? ' err' : '');
}

