 * 0x200  LD   V0  0x00      6000   ; start x = 0
 * 0x202  LD   V1  0x0E      610E   ; start y = 14
 * 0x204  LD   V2  0x01      6201   ; direction = +1
 * 0x206  LD   V3  0x04      6304   ; sprite size = 4
 * 0x208  CALL 0x210          2210   ; jump to draw loop
 * 0x20A  JP   0x20A         120A   ; idle spin (unreachable)
 *
 * 0x210  LD   I  0x220      A220   ; point at sprite data
 * 0x212  DRW  V0 V1 4       D014   ; draw sprite at (V0,V1)
 * 0x214  ADD  V0 V2         8042   ; move x
 * 0x216  LD   V4  0x00      6400   ; V4 = 0 (bound check)
 * 0x218  SE   V0  0x3C      303C   ; if x == 60
