/* ---- Run loop ---- */
let running = false;
let rafId = null;
let speed = 1; // instructions per frame

function frame() {
  if (!running) return;
  for (let i = 0; i < speed; i++) step();
  updateUI();
  rafId = requestAnimationFrame(frame);
}

function run() {
  if (running) return;
  running = true;
  audioInit();
  if (audioCtx && audioCtx.state === 'suspended') audioCtx.resume();
  rafId = requestAnimationFrame(frame);
  document.getElementById('btnRun').classList.add('active');
  document.getElementById('btnPause').classList.remove('active');
}

function pause() {
  running = false;
  if (rafId) cancelAnimationFrame(rafId);
  rafId = null;
  document.getElementById('btnRun').classList.remove('active');
  document.getElementById('btnPause').classList.add('active');
}

function doStep() {
  if (running) pause();
  step();
  updateUI();
}

function doReset() {
  pause();
  memory.fill(0);
  V.fill(0);
  I = 0; PC = PROG_START;
  stack.length = 0;
  DT = 0; ST = 0;
  keys.fill(0);
  clearDisplay();
  render();
  updateUI();
  showInstr({ text: '----', desc: '—' });
