const KEY_LABELS = ['1','2','3','4','A','B','C','D','E','F','G','H','I','J','K','L'];
const KEY_BINDS = ['1','2','3','4','Q','W','E','R','A','S','D','F','Z','X','C','V'];

function buildKeypad() {
  const kp = document.getElementById('keypad');
  for (let i = 0; i < 16; i++) {
    const d = document.createElement('div');
    d.className = 'key';
    d.dataset.key = i;
    d.innerHTML = '<div class="label">' + KEY_LABELS[i] + '</div><div class="bind">' + KEY_BINDS[i] + '</div>';
    d.addEventListener('mousedown', (e) => { e.preventDefault(); setKey(i, 1); });
    d.addEventListener('mouseup',   () => setKey(i, 0));
    d.addEventListener('mouseleave',() => setKey(i, 0));
    kp.appendChild(d);
  }
}

function setKey(k, down) {
  if (k < 0 || k > 15) return;
  keys[k] = down ? 1 : 0;
  const el = document.querySelector('.key[data-key="' + k + '"]');
  if (el) el.classList.toggle('pressed', !!down);
}

const BIND_TO_CHIP8 = {};
KEY_BINDS.forEach((b, i) => { BIND_TO_CHIP8[b] = i; BIND_TO_CHIP8[b.toLowerCase()] = i; });

document.addEventListener('keydown', (e) => {
  if (e.repeat) return;
  const k = e.key;
  if (k === ' ') { e.preventDefault(); running ? pause() : run(); return; }
  if (k === 'n' || k === 'N') { e.preventDefault(); doStep(); return; }
  const chip8 = BIND_TO_CHIP8[k];
  if (chip8 !== undefined) { e.preventDefault(); setKey(chip8, 1); }
});
document.addEventListener('keyup', (e) => {
  const chip8 = BIND_TO_CHIP8[e.key];
  if (chip8 !== undefined) setKey(chip8, 0);
});

/* ---- Events ---- */
document.getElementById('btnRun').addEventListener('click', run);
document.getElementById('btnPause').addEventListener('click', pause);
document.getElementById('btnStep').addEventListener('click', doStep);
document.getElementById('btnReset').addEventListener('click', doReset);

const speedEl = document.getElementById('speed');
speedEl.addEventListener('input', () => {
  speed = parseInt(speedEl.value, 10);
  document.getElementById('speedVal').textContent = speed;
});

document.getElementById('btnDemo').addEventListener('click', () => {
  const rom = buildDemoROM();
  loadROM(rom, 'Demo ROM');
  pause();
});

document.getElementById('romFile').addEventListener('change', (e) => {
  const file = e.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = (ev) => {
    const buf = new Uint8Array(ev.target.result);
    loadROM(buf, file.name);
    pause();
  };
  reader.onerror = () => setStatus('Failed to read file', false);
  reader.readAsArrayBuffer(file);
  e.target.value = '';
});

/* ---- Init ---- */
buildKeypad();
loadROM(buildDemoROM(), 'Demo ROM (auto)');
pause();
</script>
</body>
</html>"}

