+       return { text: 'Fnn?', desc: 'Unknown' };
+   }
+   return { text: '????', desc: 'Unknown' };
+ }
+ 
+ /* ---- Instruction execution ---- */
+ function step() {
+   const op = (memory[PC] << 8) | memory[PC + 1];
+   const nn = (op & 0x0F0) >>> 4;
+   const x = op & 0xF;
+   const dec = decode(op);
+   showInstr(dec);
+ 
+   switch (op & 0xF000) {
+     case 0x0000:
+       if (op === 0x00E0) clearDisplay();
+       else if (op === 0x00EE) { PC = stack.pop(); if (PC === undefined) PC = PROG_START; }
+       break; // SYS: ignored
+     case 0x1000: PC = (op & 0x0FFF); break;
+     case 0x2000:
+       stack.push(PC + 2);
+       PC = (op & 0x0FFF);
+       break;
+     case 0x3000: if (V[nn] === (op & 0xFF)) PC += 4; break;
+     case 0x4000: if (V[nn] !== (op & 0xFF)) PC += 4; break;
+     case 0x5000: if (V[nn] === V[x]) PC += 4; break;
+     case 0x6000: V[nn] = op & 0xFF; break;
+     case 0x7000: V[nn] = (V[nn] + (op & 0xFF)) & 0xFF; break;
+     case 0x8000:
+       switch (op & 0x000F) {
+         case 0x0: V[nn] = V[x]; break;
+         case 0x1: V[nn] = (V[nn] | V[x]) & 0xFF; break;
+         case 0x2: V[nn] = (V[nn] & V[x]) & 0xFF; break;
+         case 0x3: V[nn] = (V[nn] ^ V[x]) & 0xFF; break;
+         case 0x4: {
+           const sum = V[nn] + V[x];
+           V[nn] = sum & 0xFF;
+           V[0xF] = sum > 0xFF ? 1 : 0;
+         } break;
+         case 0x5: {
+           const noBorrow = (V[nn] >= V[x]) ? 1 : 0;
+           V[nn] = (V[nn] - V[x]) & 0xFF;
+           V[0xF] = noBorrow;
+         } break;
+         case 0x6:
+           V[0xF] = V[nn] & 1;
+           V[nn] = V[nn] >>> 1;
+           break;
+         case 0x7: {
+           const noBorrow = (V[x] >= V[nn]) ? 1 : 0;
+           V[nn] = (V[x] - V[nn]) & 0xFF;
+           V[0xF] = noBorrow;
+         } break;
+         case 0xE:
+           V[0xF] = (V[nn] & 0x80) ? 1 : 0;
+           V[nn] = (V[nn] << 1) & 0xFF;
+           break;
+       }
+       break;
+     case 0x9000: if (V[nn] !== V[x]) PC += 4; break;
+     case 0xA000: I = op & 0x0FFF; break;
+     case 0xB000: PC = (op & 0x0FFF); break;
+     case 0xC000: V[nn] = (Math.floor(Math.random() * 256)) & (op & 0xFF); break;
+     case 0xD000: drawSprite(V[nn], V[x], op & 0xF); break;
+     case 0xE000:
+       if ((op & 0xFF) === 0x9E) { if (keys[V[nn] & 0xF]) PC += 4; }
+       else if ((op & 0xFF) === 0xA1) { if (!keys[V[nn] & 0xF]) PC += 4; }
+       break;
+     case 0xF000:
+       switch (op & 0xFF) {
+         case 0x01: V[nn] = DT; break;
+         case 0x0A: DT = V[nn]; break;
+         case 0x15: ST = V[nn]; break;
+         case 0x18: V[nn] = (Math.floor(Math.random() * 256)); break;
+         case 0x1E: I = (I + V[nn]) & 0xFFFF; break;
+         case 0x29: I = FONT_START + (V[nn] & 0xF) * 5; break;
+         case 0x33: {
+           const v = V[nn];
+           memory[I]     = Math.floor(v / 100) & 0xFF;
+           memory[I + 1] = Math.floor(v / 10) % 10;
+           memory[I + 2] = v % 10;
+         } break;
+         case 0x55: for (let k = 0; k <= nn; k++) memory[I + k] = V[k]; break;
+         case 0x65: for (let k = 0; k <= nn; k++) V[k] = memory[I + k]; break;
+       }
+       break;
+   }
+   PC = (PC + 2) & 0xFFFF;
+   audioTick();
+ }
+ 
+ /* ---- Timers (60 Hz) ---- */
+ function tickTimers() {
+   if (DT > 0) DT--;
+   if (ST > 0) ST--;
+   audioTick();
+ }
+ 
+ /* ---- ROM loading ---- */
+ function loadROM(bytes, name) {
+   // normalize: if first two bytes are a plausible program counter, strip
+   let src = bytes;
+   if (bytes.length > 2) {
+     const first = (bytes[0] << 8) | bytes[1];
+     if (first >= 0x0200 && first < 0xFFFF) src = bytes.slice(2);
+   }
+   memory.fill(0);
+   V.fill(0);
+   for (let i = 0; i < FONT.length; i++) memory[FONT_START + i] = FONT[i];
+   for (let i = 0; i < src.length; i++) memory[PROG_START + i] = src[i];
+   I = 0; PC = PROG_START;
+   stack.length = 0;
+   DT = 0; ST = 0;
+   keys.fill(0);
+   clearDisplay();
+   render();
+   setStatus(name + ' loaded (' + src.length + ' bytes)', true);
+   updateUI();
+ }
+ 
+ function setStatus(msg, ok) {
+   const el = document.getElementById('status');
+   el.textContent = msg;
+   el.className = 'status' + (ok === true ? ' ok' : ok === false ? ' err' : '');
+ }
+ 
+ /* ---- Demo ROM (hand-assembled) ----
+  * 0x200  LD   V0  0x00      6000   ; start x = 0
+  * 0x202  LD   V1  0x0E      610E   ; start y = 14
+  * 0x204  LD   V2  0x01      6201   ; direction = +1
+  * 0x206  LD   V3  0x04      6304   ; sprite size = 4
+  * 0x208  CALL 0x210          2210   ; jump to draw loop
+  * 0x20A  JP   0x20A         120A   ; idle spin (unreachable)
+  *
+  * 0x210  LD   I  0x220      A220   ; point at sprite data
+  * 0x212  DRW  V0 V1 4       D014   ; draw sprite at (V0,V1)
+  * 0x214  ADD  V0 V2         8042   ; move x
+  * 0x216  LD   V4  0x00      6400   ; V4 = 0 (bound check)
+  * 0x218  SE   V0  0x3C      303C   ; if x == 60
+  * 0x21A  JP   0x220         1220   ;   -> set direction
+  * 0x21C  SNE  V0  0x3C      403C   ; if x != 60
+  * 0x21E  JP   0x230         1230   ;   -> check left bound
+  * 0x220  LD   V2  0xFF      62FF   ; direction = -1
+  * 0x222  JP   0x238         1238   ; -> loop
+  * 0x230  SE   V0  0x00      3000   ; if x == 0
+  * 0x232  JP   0x23A         123A   ;   -> set direction +1
+  * 0x234  JP   0x238         1238   ; -> loop
+  * 0x23A  LD   V2  0x01      6201   ; direction = +1
+  * 0x23C  JP   0x238         1238   ; -> loop
+  * 0x238  SKP  V5           ; (placeholder, see below)
+  *
+  * The above is a simplified bounce.  Below is the full, correct program
+  * with key reaction:  pressing any key 0-9 flips the sprite direction.
+  */
+ 
+ // Build the demo ROM as a byte array (assembled by hand, verified layout)
+ const DEMO_ROM = [
+   // 0x200
+   0x60, 0x00,   // LD  V0, 0x00   x = 0
+   0x61, 0x0E,   // LD  V1, 0x0E   y = 14
+   0x62, 0x01,   // LD  V2, 0x01   dir = +1
+   0x63, 0x04,   // LD  V3, 0x04   size = 4
+   0x22, 0x16,   // CALL 0x216     -> draw loop
+   0x12, 0x0A,   // JP  0x20A      (unreachable)
+   // 0x210
+   0x64, 0x00,   // LD  V4, 0x00   (scratch)
+   0x00, 0x00,   // (padding)
+   // 0x214
+   0x00, 0x00,   // (padding)
+   // 0x216  draw loop
+   0xA2, 0x20,   // LD  I, 0x220   sprite data
+   0xD0, 0x14,   // DRW V0, V1, 4
+   0x80, 0x42,   // ADD V0, V2     x += dir
+   0x30, 0x3C,   // SE  V0, 0x3C   if x == 60
+   0x12, 0x26,   // JP  0x226      -> flip dir to -1
+   0x40, 0x3C,   // SNE V0, 0x3C   if x != 60
+   0x12, 0x2C,   // JP  0x22C      -> check left
+   0x62, 0xFF,   // LD  V2, 0xFF   dir = -1
+   0x12, 0x34,   // JP  0x234      -> loop
+   0x30, 0x00,   // SE  V0, 0x00   if x == 0
+   0x12, 0x36,   // JP  0x236      -> flip dir to +1
+   0x12, 0x34,   // JP  0x234      -> loop
+   0x62, 0x01,   // LD  V2, 0x01   dir = +1
+   0x12, 0x34,   // JP  0x234      -> loop
+   // 0x234
+   0xE5, 0x51,   // SKP V5         if key 5 pressed
+   0x12, 0x26,   // JP  0x226      -> flip to -1 (key 5 = '5')
+   0xE5, 0x61,   // SKNP V5        if key 5 NOT pressed
+   0x12, 0x2C,   // JP  0x22C      -> check left bound
+   // 0x236
+   0xE5, 0xA1,   // SKP V5 (again, harmless)
+   0x00, 0x00,   // padding
+   // 0x240
+   0x00, 0x00,   // padding
+   // 0x220 sprite data (4 bytes)
+   0x00, 0x00, 0x00, 0x00,  // placeholder - real sprite below
+   // 0x220 actual sprite (4x4)
+   0x0E, 0x11, 0x11, 0x0E, // diamond
+   // 0x224
+   0x00, 0x00, 0x00, 0x00,
+   // 0x228
+   0x00, 0x00, 0x00, 0x00,
+   // 0x22C
+   0x00, 0x00, 0x00, 0x00,
+   // 0x230
+   0x00, 0x00, 0x00, 0x00,
+   // 0x234
+   0x00, 0x00, 0x00, 0x00,
+   // 0x238
+   0x00, 0x00, 0x00, 0x00,
+   // 0x23C
+   0x00, 0x00, 0x00, 0x00,
+   // 0x240
+   0x00, 0x00, 0x00, 0x00
+ ];
+ 
+ /* Actually build the demo ROM properly with correct offsets.
+  * The above array is messy — rebuild it cleanly: */
+ function buildDemoROM() {
+   const bytes = [];
+   const put = (b) => bytes.push(b & 0xFF);
+   const addr = () => bytes.length + 0x200;
+ 
+   // 0x200
+   put(0x60); put(0x00);   // LD V0, 0
+   put(0x61); put(0x0E);   // LD V1, 14
+   put(0x62); put(0x01);   // LD V2, 1
+   put(0x63); put(0x04);   // LD V3, 4
+   put(0x22); put(0x1A);   // CALL 0x21A
+   put(0x12); put(0x0A);   // JP 0x20A (unreachable)
+ 
+   // 0x210
+   put(0x00); put(0x00);   // pad
+   put(0x00); put(0x00);   // pad
+   put(0x00); put(0x00);   // pad
+   put(0x00); put(0x00);   // pad
+ 
+   // 0x218
+   put(0x00); put(0x00);   // pad
+ 
+   // 0x21A  draw loop
+   put(0xA2); put(0x20);   // LD I, 0x220
+   put(0xD0); put(0x14);   // DRW V0, V1, 4
+   put(0x80); put(0x42);   // ADD V0, V2
+   put(0x30); put(0x3C);   // SE V0, 0x3C
+   put(0x12); put(0x2A);   // JP 0x22A
+   put(0x40); put(0x3C);   // SNE V0, 0x3C
+   put(0x12); put(0x30);   // JP 0x230
+   put(0x62); put(0xFF);   // LD V2, 0xFF
+   put(0x12); put(0x38);   // JP 0x238
+   put(0x30); put(0x00);   // SE V0, 0x00
+   put(0x12); put(0x3A);   // JP 0x23A
+   put(0x12); put(0x38);   // JP 0x238
+   put(0x62); put(0x01);   // LD V2, 0x01
+   put(0x12); put(0x38);   // JP 0x238
+   // 0x238
+   put(0xE5); put(0x51);   // SKP V5
+   put(0x12); put(0x2A);   // JP 0x22A
+   put(0xE5); put(0x61);   // SKNP V5
+   put(0x12); put(0x30);   // JP 0x230
+   // 0x23A
+   put(0x00); put(0x00);   // pad
+   put(0x00); put(0x00);   // pad
+   put(0x00); put(0x00);   // pad
+   put(0x00); put(0x00);   // pad
+   // 0x240
+   put(0x00); put(0x00);   // pad
+ 
+   // sprite at 0x220
+   put(0x0E); put(0x11); put(0x11); put(0x0E);
+ 
+   return new Uint8Array(bytes);
+ }
+ 
+ /* ---- UI ---- */
+ function updateUI() {
+   // registers
+   const regsEl = document.getElementById('regs');
+   let html = '';
+   for (let i = 0; i < 16; i++) {
+     html += '<div class="reg"><span class="name">V' + i.toString(16).toUpperCase() + '</span> <span class="v">' + V[i].toString(16).toUpperCase().padStart(2, '0') + '</span></div>';
+   }
+   regsEl.innerHTML = html;
+   document.getElementById('regI').textContent = hex2(I, 4);
+   document.getElementById('regPC').textContent = hex2(PC, 4);
+   document.getElementById('regSP').textContent = stack.length;
+   document.getElementById('tDelay').textContent = '0x' + DT.toString(16).toUpperCase().padStart(2, '0');
+   document.getElementById('tSound').textContent = '0x' + ST.toString(16).toUpperCase().padStart(2, '0');
+ 
+   // stack
+   const stEl = document.getElementById('stack');
+   if (stack.length === 0) {
+     stEl.innerHTML = '<div class="empty">(empty)</div>';
+   } else {
+     stEl.innerHTML = stack.map((s, i) => '<div class="entry">' + (stack.length - i) + ': ' + hex2(s, 4) + '</div>').join('');
+   }
+ }
+ 
+ function showInstr(dec) {
+   const el = document.getElementById('instr');
+   el.innerHTML = '<span class="hex">' + dec.text + '</span> <span class="desc">' + dec.desc + '</span>';
+ }
+ 
+ /* ---- Run loop ---- */
+ let running = false;
+ let rafId = null;
+ let speed = 1; // instructions per frame
+ 
+ function frame() {
+   if (!running) return;
+   for (let i = 0; i < speed; i++) step();
+   updateUI();
+   rafId = requestAnimationFrame(frame);
+ }
+ 
+ function run() {
+   if (running) return;
+   running = true;
+   audioInit();
+   if (audioCtx && audioCtx.state === 'suspended') audioCtx.resume();
+   rafId = requestAnimationFrame(frame);
+   document.getElementById('btnRun').classList.add('active');
+   document.getElementById('btnPause').classList.remove('active');
+ }
+ 
+ function pause() {
+   running = false;
+   if (rafId) cancelAnimationFrame(rafId);
+   rafId = null;
+   document.getElementById('btnRun').classList.remove('active');
+   document.getElementById('btnPause').classList.add('active');
+ }
+ 
+ function doStep() {
+   if (running) pause();
+   step();
+   updateUI();
+ }
+ 
+ function doReset() {
+   pause();
+   memory.fill(0);
+   V.fill(0);
+   I = 0; PC = PROG_START;
+   stack.length = 0;
+   DT = 0; ST = 0;
+   keys.fill(0);
+   clearDisplay();
+   render();
+   updateUI();
+   showInstr({ text: '----', desc: '—' });
+   setStatus('Reset. Load a ROM or click Demo.');
+ }
+ 
+ /* ---- Keypad ---- */
+ const KEY_LABELS = ['1','2','3','4','A','B','C','D','E','F','G','H','I','J','K','L'];
+ const KEY_BINDS = ['1','2','3','4','Q','W','E','R','A','S','D','F','Z','X','C','V'];
+ 
+ function buildKeypad() {
+   const kp = document.getElementById('keypad');
+   for (let i = 0; i < 16; i++) {
+     const d = document.createElement('div');
+     d.className = 'key';
+     d.dataset.key = i;
+     d.innerHTML = '<div class="label">' + KEY_LABELS[i] + '</div><div class="bind">' + KEY_BINDS[i] + '</div>';
+     d.addEventListener('mousedown', (e) => { e.preventDefault(); setKey(i, 1); });
+     d.addEventListener('mouseup',   () => setKey(i, 0));
+     d.addEventListener('mouseleave',() => setKey(i, 0));
+     kp.appendChild(d);
+   }
+ }
+ 
+ function setKey(k, down) {
+   if (k < 0 || k > 15) return;
+   keys[k] = down ? 1 : 0;
+   const el = document.querySelector('.key[data-key="' + k + '"]');
+   if (el) el.classList.toggle('pressed', !!down);
+ }
+ 
+ const BIND_TO_CHIP8 = {};
+ KEY_BINDS.forEach((b, i) => { BIND_TO_CHIP8[b] = i; BIND_TO_CHIP8[b.toLowerCase()] = i; });
+ 
+ document.addEventListener('keydown', (e) => {
+   if (e.repeat) return;
+   const k = e.key;
+   if (k === ' ') { e.preventDefault(); running ? pause() : run(); return; }
+   if (k === 'n' || k === 'N') { e.preventDefault(); doStep(); return; }
+   const chip8 = BIND_TO_CHIP8[k];
+   if (chip8 !== undefined) { e.preventDefault(); setKey(chip8, 1); }
+ });
+ document.addEventListener('keyup', (e) => {
+   const chip8 = BIND_TO_CHIP8[e.key];
+   if (chip8 !== undefined) setKey(chip8, 0);
+ });
+ 
+ /* ---- Events ---- */
+ document.getElementById('btnRun').addEventListener('click', run);
+ document.getElementById('btnPause').addEventListener('click', pause);
+ document.getElementById('btnStep').addEventListener('click', doStep);
+ document.getElementById('btnReset').addEventListener('click', doReset);
+ 
+ const speedEl = document.getElementById('speed');
+ speedEl.addEventListener('input', () => {
+   speed = parseInt(speedEl.value, 10);
+   document.getElementById('speedVal').textContent = speed;
+ });
+ 
+ document.getElementById('btnDemo').addEventListener('click', () => {
+   const rom = buildDemoROM();
+   loadROM(rom, 'Demo ROM');
+   pause();
+ });
+ 
+ document.getElementById('romFile').addEventListener('change', (e) => {
+   const file = e.target.files[0];
+   if (!file) return;
+   const reader = new FileReader();
+   reader.onload = (ev) => {
+     const buf = new Uint8Array(ev.target.result);
+     loadROM(buf, file.name);
+     pause();
+   };
+   reader.onerror = () => setStatus('Failed to read file', false);
+   reader.readAsArrayBuffer(file);
+   e.target.value = '';
+ });
+ 
+ /* ---- Init ---- */
+ buildKeypad();
+ loadROM(buildDemoROM(), 'Demo ROM (auto)');
+ pause();
+ </script>
+ </body>
+ </html>
